package api

import (
	"net/http"
	"time"
)

type Client struct {
	BaseURL string
	Timeout time.Duration
	HTTP    *http.Client
}

func NewClient(baseURL string) *Client {
	return &Client{
		BaseURL: baseURL,
		Timeout: timeout, // Assign the new parameter to the Timeout field
		HTTP:    &http.Client{},
	}
}

func NewDefaultClient() *Client {
	return NewClient("https://api.example.com")
}
