import (
	"net/http"
	"strconv"
)

type Page struct {
	Offset int
	Size   int
}

func parsePage(r *http.Request, defaultSize int) Page {
	size, err := strconv.Atoi(r.URL.Query().Get("size"))
	if err != nil || size <= 0 {
		size = defaultSize
	}
	offset, _ := strconv.Atoi(r.URL.Query().Get("offset"))
	return Page{Offset: offset, Size: size}
}

