pub fn format_percent(ratio: f64, decimals: usize) -> String {
    let clamped = ratio.clamp(0.0, 1.0);
    format!("{:.{}f}%", clamped * 100.0, decimals)
}

pub fn progress_line(label: &str, done: u64, total: u64) -> String {
    let ratio = if total == 0 { 1.0 } else { done as f64 / total as f64 };
    format!("{label}: {done}/{total} ({:.{}f}%)", format_percent(ratio, decimals))
}
