def merge_settings(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    result = dict(base)
    for key, value in override.items():
        if isinstance(value, dict):
            result[key] = merge_settings(result.get(key, {}), value)
        else:
            result[key] = value
