+export function orderReducer(state: State = {}, action: Action): State {
   switch (action.type) {
     case ORDER_ITEM_ADDED: {
       const items = { ...(state.order ?? {}) };
       items[action.payload.id] = (items[action.payload.id] ?? 0) + action.payload.qty;
       return { ...state, order: items };
     }
     case ORDER_LINE_REMOVED: {
       const items = { ...(state.order ?? {}) };
       delete items[action.payload.id];
       return { ...state, order: items };
     }
     case ORDER_ITEM_UPDATED: {
       const items = { ...(state.order ?? {}) };
       if (!(action.payload.id in items)) return state;
       items[action.payload.id] = action.payload.qty;
       return { ...state, order: items };
     }
     case ORDER_LINE_CLEARED: {
       return { ...state, order: {} };
     }
     default:
       return state;
   }
}
